create or replace function public.verify_own_terminal_lock_pin(p_pin text) returns boolean language plpgsql security definer set search_path=public,extensions as $$ declare credential public.staff_pin_credentials%rowtype; begin if p_pin !~ '^[0-9]{6}$' then return false; end if; select * into credential from public.staff_pin_credentials where user_id=auth.uid() for update; if not found or credential.status<>'ACTIVE' or (credential.locked_until is not null and credential.locked_until>now()) then return false; end if; if credential.pin_hash=crypt(p_pin,credential.pin_hash) then update public.staff_pin_credentials set failed_attempts=0,locked_until=null where user_id=auth.uid(); perform public.write_pos_audit('TERMINAL_UNLOCKED','PROFILE',auth.uid(),null,jsonb_build_object('result','SUCCESS')); return true; end if; update public.staff_pin_credentials set failed_attempts=least(failed_attempts+1,20),locked_until=case when failed_attempts+1>=5 then now()+interval '5 minutes' else locked_until end where user_id=auth.uid(); return false; end $$;
grant execute on function public.verify_own_terminal_lock_pin(text) to authenticated;
